<script setup lang="ts">
import {onMounted,ref,watch,computed} from 'vue'
import {useSessionStore} from '../../../stores/session'
import {usePolling} from '../../../composables/usePolling'
import AccountLifecyclePanel from './AccountLifecyclePanel.vue'
import {accountsApi,type Account,type AccountDetail,type Role,type Permissions,type PermissionInfo} from '../../../api/accounts'
import {bytes,date,errorText} from '../../../utils/format'
import StorageAccounts from '../storage/StorageAccounts.vue'
import PermissionEditor from './PermissionEditor.vue'
import ApproveAccessDialog from './ApproveAccessDialog.vue'
import {adminUsers,type NewUser} from '../../../api/adminUsers'
const session=useSessionStore()
const can=(key:string)=>session.can(key)
const props=defineProps<{refreshKey:number}>()
const emit=defineEmits<{created:[]}>()
const creating=ref(false),grantUser=ref<Account|null>(null),submitError=ref('')
function closeDialog(){creating.value=false;grantUser.value=null;submitError.value=''}
async function create(payload:NewUser){if(busy.value)return;busy.value=true;submitError.value='';try{await adminUsers.create(payload);closeDialog();emit('created');await load();message.value='Аккаунт создан'}catch(e){submitError.value=errorText(e)}finally{busy.value=false}}
async function saveGrants(ids:string[]){if(!grantUser.value)return;busy.value=true;submitError.value='';try{await adminUsers.save(grantUser.value.id,ids);closeDialog();message.value='Доступ обновлён'}catch(e){submitError.value=errorText(e)}finally{busy.value=false}}
const rows=ref<Account[]>([]),stats=ref<{total:number;active:number;blocked:number}|null>(null),more=ref(false),search=ref(''),loading=ref(false),busy=ref(false),error=ref(''),message=ref('')
const detail=ref<AccountDetail|null>(null),roles=ref<Role[]>([]),catalog=ref<Record<string,PermissionInfo>>({}),name=ref(''),role=ref(''),overrides=ref<Permissions>({}),tab=ref('main'),password=ref('')
const events=ref<Array<{id:number;at:string;actor:string;target:string;action:string}>>([])
async function load(append=false){if(loading.value)return;loading.value=true;try{const data=await accountsApi.list(search.value,append?rows.value.length:0);rows.value=append?[...rows.value,...data.items]:data.items;stats.value=data.stats;more.value=data.has_more;error.value=''}catch(e){error.value=errorText(e)}finally{loading.value=false}}
async function open(id:number){if(loading.value||busy.value)return;loading.value=true;error.value='';try{const [d,r]=await Promise.all([accountsApi.detail(id),can("accounts.roles")?accountsApi.roles():Promise.resolve({items:[],catalog:{}})]);detail.value=d;roles.value=r.items;catalog.value=r.catalog;name.value=d.display_name;role.value=d.role_id;overrides.value={...d.permission_overrides};tab.value='main';message.value='';password.value=''}catch(e){error.value=errorText(e)}finally{loading.value=false}}
async function save(){if(!detail.value)return;busy.value=true;error.value='';try{detail.value=await accountsApi.edit(detail.value.id,{display_name:name.value,role_id:role.value,overrides:overrides.value});message.value='Настройки сохранены';await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
const detailTabs=computed(()=>[['main','Основное'],['rights','Права'],...(can("accounts.storage")?[['storage','Хранилище']]:[]),...(can("accounts.sessions")||can("accounts.password")||can("accounts.block")||can("accounts.revoke")||can("accounts.delete")||can("accounts.transfer")?[['security','Безопасность']]:[])])
function choose(next:string){tab.value=next;message.value='';if(next!=='security')password.value=''}
async function security(action:string,sessionId?:string){if(!detail.value||!window.confirm('Подтвердите действие с аккаунтом «'+detail.value.username+'».'))return;busy.value=true;try{await accountsApi.security(detail.value.id,action,action==='reset_password'?password.value:undefined,sessionId);detail.value=await accountsApi.detail(detail.value.id);password.value='';message.value='Действие выполнено';await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function refreshDetail(){if(!detail.value)return;try{detail.value=await accountsApi.detail(detail.value.id)}catch(e){error.value=errorText(e)}}
async function history(){try{events.value=(await accountsApi.events()).items}catch(e){error.value=errorText(e)}}
onMounted(()=>load());watch(()=>props.refreshKey,()=>load())
</script>
<template><section class="panel stack" aria-label="Аккаунты"><p v-if="error" class="alert error" role="alert">{{error}}</p>
<template v-if="!detail"><div class="row between wrap"><h2>Пользователи</h2><button v-if="can('accounts.create')&&can('accounts.assign')&&can('accounts.roles')" class="btn primary" @click="creating=true">Создать пользователя</button></div><div v-if="stats" class="row wrap"><span>Всего: <strong>{{stats.total}}</strong></span><span>Активные: <strong>{{stats.active}}</strong></span><span>Заблокированные: <strong>{{stats.blocked}}</strong></span></div>
<form class="row wrap" @submit.prevent="load()"><input v-model="search" placeholder="Имя или логин" aria-label="Поиск аккаунтов"/><button class="btn" :disabled="loading">Найти</button></form>
<div v-for="u in rows" :key="u.id" class="row wrap"><button class="btn account-entry" :disabled="loading||busy" @click="open(u.id)"><span><strong>{{u.display_name||u.username}}</strong><small class="meta">{{u.display_name?u.username+' · ':''}}{{u.role_name}}</small></span><span>{{u.blocked?'Заблокирован':'Активен'}}<small v-if="can('accounts.storage')" class="meta">{{bytes(u.usage?.allocated_bytes)}} / {{u.storage_limit_bytes==null?'Без ограничения':bytes(u.storage_limit_bytes)}}</small><progress v-if="u.quota?.enabled&&u.storage_limit_bytes!=null&&u.storage_limit_bytes>0" :value="u.quota.used_bytes+u.quota.reserved_bytes" :max="u.storage_limit_bytes"/><small v-if="u.storage_limit_bytes!=null&&!u.quota?.enabled" class="meta">Квота сейчас выключена</small></span></button><button v-if="u.role_id!=='owner'&&can('accounts.grants')" class="btn small" @click="grantUser=u">Изменить доступ к отчётам</button></div>
<p v-if="message" role="status">{{message}}</p><button v-if="more" class="btn" @click="load(true)">Показать ещё</button><details v-if="can('accounts.history')" @toggle="history"><summary>История административных действий</summary><div v-for="event in events" :key="event.id" class="row wrap"><span>{{date(event.at)}}</span><span>{{event.actor}} · {{event.action}} · {{event.target}}</span></div></details></template>
<template v-else><button class="btn" :disabled="busy" @click="detail=null">К пользователям</button><h2>{{detail.display_name||detail.username}}</h2><div class="row wrap"><button :disabled="busy" v-for="[key,label] in detailTabs" :key="key" class="btn small" :aria-pressed="tab===key" @click="choose(key)">{{label}}</button></div>
<p v-if="detail.role_id==='owner'" class="meta">Владелец защищён. Пароль управляется через действующий механизм установки.</p>
<template v-if="tab==='main'"><label class="field">Имя<input v-model="name" :disabled="detail.role_id==='owner'||!can('accounts.edit')"/></label><p>Логин: {{detail.username}}</p><label class="field">Роль<select v-model="role" :disabled="detail.role_id==='owner'||!can('accounts.assign')||!can('accounts.roles')"><option v-for="r in roles.filter(r=>r.id!=='owner'||detail?.role_id==='owner')" :key="r.id" :value="r.id">{{r.name}}</option></select></label><p>Статус: {{detail.blocked?'Заблокирован':'Активен'}}</p><p>Создан: {{date(detail.created_at)}} · Последний вход: {{date(detail.last_login_at)}}</p><button v-if="detail.role_id!=='owner'&&(can('accounts.edit')||can('accounts.assign'))" class="btn primary" :disabled="busy" @click="save">Сохранить</button></template>
<template v-else-if="tab==='rights'"><p v-if="detail.role_id==='owner'" class="meta">Полный защищённый доступ.</p><PermissionEditor v-else v-model="overrides" :catalog="catalog" :inherited="roles.find(r=>r.id===role)?.permissions||detail.role_permissions" :disabled="!can('accounts.overrides')||busy"/><div v-if="detail.role_id!=='owner'&&can('accounts.overrides')" class="row wrap"><button class="btn" @click="overrides={}">Сбросить все до роли</button><button class="btn primary" :disabled="busy" @click="save">Сохранить права</button></div></template>
<StorageAccounts v-else-if="tab==='storage'" :key="detail.id" :account-id="String(detail.id)"/>
<template v-else-if="tab==='security'"><p v-if="can('accounts.sessions')">Активных сессий: {{detail.sessions.length}}</p><div v-for="s in detail.sessions" :key="s.session_id" class="row between wrap"><span>{{date(s.created_at)}} — {{date(s.expires_at)}}</span><button v-if="detail.role_id!=='owner'&&can('accounts.revoke')" class="btn small" :disabled="busy" @click="security('revoke_session',s.session_id)">Завершить</button></div><template v-if="detail.role_id!=='owner'"><button v-if="can('accounts.revoke')" class="btn" :disabled="busy" @click="security('revoke_all')">Завершить все сессии</button><label v-if="can('accounts.password')" class="field">Новый пароль<input v-model="password" type="password" autocomplete="new-password" minlength="12" maxlength="256"/></label><button v-if="can('accounts.password')" class="btn" :disabled="busy||password.length<12" @click="security('reset_password')">Сбросить пароль</button><button v-if="can('accounts.block')" class="btn danger" :disabled="busy" @click="security(detail.blocked?'unblock':'block')">{{detail.blocked?'Разблокировать':'Заблокировать'}}</button><AccountLifecyclePanel v-if="can('accounts.storage')&&(can('accounts.delete')||can('accounts.transfer'))" :account="detail" @deleted="detail=null;load()" @changed="load();refreshDetail()"/></template></template>
<p v-if="message" role="status">{{message}}</p></template></section><ApproveAccessDialog v-if="creating" creating :busy="busy" :submit-error="submitError" @create="create" @cancel="closeDialog"/><ApproveAccessDialog v-else-if="grantUser" :email="grantUser.username" :busy="busy" :submit-error="submitError" :load-grants="()=>adminUsers.grants(grantUser!.id)" @approve="saveGrants" @cancel="closeDialog"/></template>
<style scoped>.account-entry{display:flex;justify-content:space-between;text-align:left;gap:12px;white-space:normal;min-width:0;overflow-wrap:anywhere}.account-entry small{display:block}.account-entry progress{display:block;max-width:100%}</style>
